import{_ as a,H as l,f as p,i}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"《数据结构与算法之美》学习指导手册","description":"","frontmatter":{},"headers":[{"level":2,"title":"1.复杂度分析","slug":"_1-复杂度分析","link":"#_1-复杂度分析","children":[]},{"level":2,"title":"2.数组、栈、队列","slug":"_2-数组、栈、队列","link":"#_2-数组、栈、队列","children":[]},{"level":2,"title":"3.链表","slug":"_3-链表","link":"#_3-链表","children":[]},{"level":2,"title":"4.递归","slug":"_4-递归","link":"#_4-递归","children":[]},{"level":2,"title":"5.排序、二分查找","slug":"_5-排序、二分查找","link":"#_5-排序、二分查找","children":[]},{"level":2,"title":"6.跳表","slug":"_6-跳表","link":"#_6-跳表","children":[]},{"level":2,"title":"7.散列表","slug":"_7-散列表","link":"#_7-散列表","children":[]},{"level":2,"title":"8.哈希算法","slug":"_8-哈希算法","link":"#_8-哈希算法","children":[]},{"level":2,"title":"9.二叉树","slug":"_9-二叉树","link":"#_9-二叉树","children":[]},{"level":2,"title":"10.红黑树","slug":"_10-红黑树","link":"#_10-红黑树","children":[]},{"level":2,"title":"11. B+树","slug":"_11-b-树","link":"#_11-b-树","children":[]},{"level":2,"title":"12.堆与堆排序","slug":"_12-堆与堆排序","link":"#_12-堆与堆排序","children":[]},{"level":2,"title":"13.图的表示","slug":"_13-图的表示","link":"#_13-图的表示","children":[]},{"level":2,"title":"14.深度广度优先搜索","slug":"_14-深度广度优先搜索","link":"#_14-深度广度优先搜索","children":[]},{"level":2,"title":"15.拓扑排序、最短路径、A*算法","slug":"_15-拓扑排序、最短路径、a-算法","link":"#_15-拓扑排序、最短路径、a-算法","children":[]},{"level":2,"title":"16.字符串匹配（BF、RK）","slug":"_16-字符串匹配-bf、rk","link":"#_16-字符串匹配-bf、rk","children":[]},{"level":2,"title":"17.字符串匹配（BM、KMP、AC自动机）","slug":"_17-字符串匹配-bm、kmp、ac自动机","link":"#_17-字符串匹配-bm、kmp、ac自动机","children":[]},{"level":2,"title":"18.字符串匹配（Trie）","slug":"_18-字符串匹配-trie","link":"#_18-字符串匹配-trie","children":[]},{"level":2,"title":"19.位图","slug":"_19-位图","link":"#_19-位图","children":[]},{"level":2,"title":"20.四种算法思想","slug":"_20-四种算法思想","link":"#_20-四种算法思想","children":[]}],"relativePath":"数据结构与算法之美/《数据结构与算法之美》学习指导手册.md","filePath":"数据结构与算法之美/《数据结构与算法之美》学习指导手册.md","lastUpdated":1779820813000}'),t={name:"数据结构与算法之美/《数据结构与算法之美》学习指导手册.md"};function r(h,e,n,_,o,d){return l(),p("div",null,[...e[0]||(e[0]=[i('<h1 id="《数据结构与算法之美》学习指导手册" tabindex="-1">《数据结构与算法之美》学习指导手册 <a class="header-anchor" href="#《数据结构与算法之美》学习指导手册" aria-label="Permalink to &quot;《数据结构与算法之美》学习指导手册&quot;">​</a></h1><p>你好，我是王争。</p><p>在设计专栏内容的时候，为了兼顾不同基础的同学，我在内容上做到了难易结合，既有简单的数组、链表、栈、队列这些基础内容，也有红黑树、BM、KMP这些难度较大的算法。但是，对于初学者来说，一下子面对这么多知识，可能还是比较懵。</p><p>我觉得，对于初学者来说，先把最简单、最基础、最重要的知识点掌握好，再去研究难度较高、更加高级的知识点，这样由易到难、循序渐进的学习路径，无疑是最合理的。</p><p>基于这个路径，我对专栏内容，重新做了一次梳理，希望给你一份具体、明确、有效的学习指导。我会写清楚 <strong>每个知识点的难易程度、需要你掌握到什么程度、具体如何来学习</strong>。</p><p>如果你是数据结构和算法的初学者，或者你觉得自己的基础比较薄弱，希望这份学习指导，能够让你学起来能更加有的放矢，能把精力、时间花在刀刃上，获得更好的学习效果。</p><p>下面，我先给出一个大致的学习路线。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/91541/54163f16e152f71b8f91d3fba652cf48.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%95%B0%E6%8D%AE%E7%BB%93%E6%9E%84%E4%B8%8E%E7%AE%97%E6%B3%95%E4%B9%8B%E7%BE%8E/images/91541/54163f16e152f71b8f91d3fba652cf48.jpg" alt=""></a></p><p>（建议保存后查看大图）</p><p>现在，针对每个知识点，我再给你逐一解释一下。我这里先说明一下，下面标记的难易程度、是否重点、掌握程度，都只是针对初学者来说的，如果你已经有一定基础，可以根据自己的情况，安排自己的学习。</p><h2 id="_1-复杂度分析" tabindex="-1">1.复杂度分析 <a class="header-anchor" href="#_1-复杂度分析" aria-label="Permalink to &quot;1.复杂度分析&quot;">​</a></h2><p>尽管在专栏中，我只用了两节课的内容，来讲复杂度分析这个知识点。但是，我想说的是，它真的非常重要。你必须要牢牢掌握这两节，基本上要做到，简单代码能很快分析出时间、空间复杂度；对于复杂点的代码，比如递归代码，你也要掌握专栏中讲到的两种分析方法：递推公式和递归树。</p><p>对于初学者来说，光看入门篇的两节复杂度分析文章，可能还不足以完全掌握复杂度分析。不过，在后续讲解每种数据结构和算法的时候，我都有详细分析它们的时间、空间复杂度。所以，你可以在学习专栏中其他章节的时候，再不停地、有意识地去训练自己的复杂度分析能力。</p><p>难易程度：Medium</p><p>是否重点：10分</p><p>掌握程度：在不看我的分析的情况下，能自行分析专栏中大部分数据结构和算法的时间、空间复杂度</p><h2 id="_2-数组、栈、队列" tabindex="-1">2.数组、栈、队列 <a class="header-anchor" href="#_2-数组、栈、队列" aria-label="Permalink to &quot;2.数组、栈、队列&quot;">​</a></h2><p>这一部分内容非常简单，初学者学起来也不会很难。但是，作为基础的数据结构，数组、栈、队列，是后续很多复杂数据结构和算法的基础，所以，这些内容你一定要掌握。</p><p>难易程度：Easy</p><p>是否重点：8分</p><p>掌握程度：能自己实现动态数组、栈、队列</p><h2 id="_3-链表" tabindex="-1">3.链表 <a class="header-anchor" href="#_3-链表" aria-label="Permalink to &quot;3.链表&quot;">​</a></h2><p>链表非常重要！虽然理论内容不多，但链表上的操作却很复杂。所以，面试中经常会考察，你一定要掌握。而且，我这里说“掌握”不只是能看懂专栏中的内容，还能将专栏中提到的经典链表题目，比如链表反转、求中间结点等，轻松无bug地实现出来。</p><p>难易程度：Medium</p><p>是否重点：9分</p><p>掌握程度：能轻松写出经典链表题目代码</p><h2 id="_4-递归" tabindex="-1">4.递归 <a class="header-anchor" href="#_4-递归" aria-label="Permalink to &quot;4.递归&quot;">​</a></h2><p>对于初学者来说，递归代码非常难掌握，不管是读起来，还是写起来。但是，这道坎你必须要跨过，跨不过就不能算是入门数据结构和算法。我们后面讲到的很多数据结构和算法的代码实现，都要用到递归。</p><p>递归相关的理论知识也不多，所以还是要多练。你可以先在网上找些简单的题目练手，比如斐波那契数列、求阶乘等，然后再慢慢过渡到更加有难度的，比如归并排序、快速排序、二叉树的遍历、求高度，最后是回溯八皇后、背包问题等。</p><p>难易程度：Hard</p><p>是否重点：10分</p><p>掌握程度：轻松写出二叉树遍历、八皇后、背包问题、DFS的递归代码</p><h2 id="_5-排序、二分查找" tabindex="-1">5.排序、二分查找 <a class="header-anchor" href="#_5-排序、二分查找" aria-label="Permalink to &quot;5.排序、二分查找&quot;">​</a></h2><p>这一部分并不难，你只需要能看懂我专栏里的内容即可。</p><p>难易程度：Easy</p><p>是否重点：7分</p><p>掌握程度：能自己把各种排序算法、二分查找及其变体代码写一遍就可以了</p><h2 id="_6-跳表" tabindex="-1">6.跳表 <a class="header-anchor" href="#_6-跳表" aria-label="Permalink to &quot;6.跳表&quot;">​</a></h2><p>对于初学者来说，并不需要非得掌握跳表，所以，如果没有精力，这一章节可以先跳过。</p><p>难易程度：Medium</p><p>是否重点：6分</p><p>掌握程度：初学者可以先跳过。如果感兴趣，看懂专栏内容即可，不需要掌握代码实现</p><h2 id="_7-散列表" tabindex="-1">7.散列表 <a class="header-anchor" href="#_7-散列表" aria-label="Permalink to &quot;7.散列表&quot;">​</a></h2><p>尽管散列表的内容我讲了很多，有三节课。但是，总体上来讲，这块内容理解起来并不难。但是，作为一种应用非常广泛的数据结构，你还是要掌握牢固散列表。</p><p>难易程度：Medium</p><p>是否重点：8分</p><p>掌握程度：对于初学者来说，自己能代码实现一个拉链法解决冲突的散列表即可</p><h2 id="_8-哈希算法" tabindex="-1">8.哈希算法 <a class="header-anchor" href="#_8-哈希算法" aria-label="Permalink to &quot;8.哈希算法&quot;">​</a></h2><p>这部分纯粹是为了开拓思路，初学者可以略过。</p><p>难易程度：Easy</p><p>是否重点：3分</p><p>掌握程度：可以暂时不看</p><h2 id="_9-二叉树" tabindex="-1">9.二叉树 <a class="header-anchor" href="#_9-二叉树" aria-label="Permalink to &quot;9.二叉树&quot;">​</a></h2><p>这一部分非常重要！二叉树在面试中经常会被考到，所以要重点掌握。但是我这里说的二叉树，并不包含专栏中红黑树的内容。红黑树我们待会再讲。</p><p>难易程度：Medium</p><p>是否重点：9分</p><p>掌握程度：能代码实现二叉树的三种遍历算法、按层遍历、求高度等经典二叉树题目</p><h2 id="_10-红黑树" tabindex="-1">10.红黑树 <a class="header-anchor" href="#_10-红黑树" aria-label="Permalink to &quot;10.红黑树&quot;">​</a></h2><p>对于初学者来说，这一节课完全可以不看。</p><p>难易程度：Hard</p><p>是否重点：3分</p><p>掌握程度：初学者不用把时间浪费在上面</p><h2 id="_11-b-树" tabindex="-1">11. B+树 <a class="header-anchor" href="#_11-b-树" aria-label="Permalink to &quot;11\\. B+树&quot;">​</a></h2><p>虽然B+树也算是比较高级的一种数据结构了，但是对初学者来说，也不是重点。有时候面试的时候还是会问的，所以这一部分内容，你能看懂专栏里的讲解就可以了。</p><p>难易程度：Medium</p><p>是否重点：5分</p><p>掌握程度：可看可不看</p><h2 id="_12-堆与堆排序" tabindex="-1">12.堆与堆排序 <a class="header-anchor" href="#_12-堆与堆排序" aria-label="Permalink to &quot;12.堆与堆排序&quot;">​</a></h2><p>这一部分内容不是很难，初学者也是要掌握的。</p><p>难易程度：Medium</p><p>是否重点：8分</p><p>掌握程度：能代码实现堆、堆排序，并且掌握堆的三种应用（优先级队列、Top k、中位数）</p><h2 id="_13-图的表示" tabindex="-1">13.图的表示 <a class="header-anchor" href="#_13-图的表示" aria-label="Permalink to &quot;13.图的表示&quot;">​</a></h2><p>图的内容很多，但是初学者不需要掌握那么多。一般BAT等大厂面试，不怎么会面试有关图的内容，因为面试官可能也对这块不会很熟悉哈：）。但是，最基本图的概念、表示方法还是要掌握的。</p><p>难易程度：Easy</p><p>是否重点：8分</p><p>掌握程度：理解图的三种表示方法（邻接矩阵、邻接表、逆邻接表），能自己代码实现</p><h2 id="_14-深度广度优先搜索" tabindex="-1">14.深度广度优先搜索 <a class="header-anchor" href="#_14-深度广度优先搜索" aria-label="Permalink to &quot;14.深度广度优先搜索&quot;">​</a></h2><p>这算是图上最基础的遍历或者说是搜索算法了，所以还是要掌握一下。这两种算法的原理都不难哈，但是代码实现并不简单，一个用到了队列，另一个用到了递归。对于初学者来说，看懂这两个代码实现就是一个挑战！可以等到其他更重要的内容都掌握之后，再来挑战，也是可以的。</p><p>难易程度：Hard</p><p>是否重点：8分</p><p>掌握程度：能代码实现广度优先、深度优先搜索算法</p><h2 id="_15-拓扑排序、最短路径、a-算法" tabindex="-1">15.拓扑排序、最短路径、A*算法 <a class="header-anchor" href="#_15-拓扑排序、最短路径、a-算法" aria-label="Permalink to &quot;15.拓扑排序、最短路径、A\\*算法&quot;">​</a></h2><p>这几个算法稍微高级点。如果你能轻松实现深度、广度优先搜索，那看懂这三个算法不成问题。不过，这三种算法不是重点。面试不会考的。</p><p>难易程度：Hard</p><p>是否重点：5分</p><p>掌握程度：有时间再看，暂时可以不看</p><h2 id="_16-字符串匹配-bf、rk" tabindex="-1">16.字符串匹配（BF、RK） <a class="header-anchor" href="#_16-字符串匹配-bf、rk" aria-label="Permalink to &quot;16.字符串匹配（BF、RK）&quot;">​</a></h2><p>BF非常简单，RK稍微复杂点，但都不难。这个最好还是掌握下。</p><p>难易程度：Easy</p><p>是否重点：7分</p><p>掌握程度：能实践BF算法，能看懂RK算法</p><h2 id="_17-字符串匹配-bm、kmp、ac自动机" tabindex="-1">17.字符串匹配（BM、KMP、AC自动机） <a class="header-anchor" href="#_17-字符串匹配-bm、kmp、ac自动机" aria-label="Permalink to &quot;17.字符串匹配（BM、KMP、AC自动机）&quot;">​</a></h2><p>这三个算法都挺难的，对于算法有一定基础的人来说，看懂也不容易。所以，对于初学者来说，千万别浪费时间在这上面。即便有余力，看懂就好了，不用非得能自己实现。</p><p>难易程度：Hard</p><p>是否重点：3分</p><p>掌握程度：初学者不用把时间浪费在上面</p><h2 id="_18-字符串匹配-trie" tabindex="-1">18.字符串匹配（Trie） <a class="header-anchor" href="#_18-字符串匹配-trie" aria-label="Permalink to &quot;18.字符串匹配（Trie）&quot;">​</a></h2><p>这个还是要能看懂，不过不需要能代码实现。有些面试官喜欢考这个东西，主要是结合应用场景来考察，只是看你知不知道要用Trie树这个东西。</p><p>难易程度：Medium</p><p>是否重点：7分</p><p>掌握程度：能看懂，知道特点、应用场景即可，不要求代码实现</p><h2 id="_19-位图" tabindex="-1">19.位图 <a class="header-anchor" href="#_19-位图" aria-label="Permalink to &quot;19.位图&quot;">​</a></h2><p>位图不是重点，如果有余力最好掌握一下。</p><p>难易程度：Easy</p><p>是否重点：6分</p><p>掌握程度：看懂即可，能自己实现一个位图结构最好</p><h2 id="_20-四种算法思想" tabindex="-1">20.四种算法思想 <a class="header-anchor" href="#_20-四种算法思想" aria-label="Permalink to &quot;20.四种算法思想&quot;">​</a></h2><p>这个是重点，也是难点。贪心、分治、回溯、动态规划，每一个都不简单，其中动态规划又是最难、最烧脑的。要应付FLAG这样公司的面试，必须拿下这块内容。但是呢，学习要循序渐进，这块内容的学习可以放到最后，做个长时间的学习计划来攻克。</p><p>这块内容理论的东西不多，要想真的掌握，还是要大量刷题。</p><p>难易程度：Hard</p><p>是否重点：10分</p><p>掌握程度：可以放到最后，但是一定要掌握！做到能实现Leetcode上Medium难度的题目</p><hr><p>学而时习之，专栏虽然已经结束，但是学习的同学和留言依旧源源不断。希望这份学习指导手册对你有帮助，也欢迎你继续给我留言，和大家一起交流、学习、进步。</p>',115)])])}const u=a(t,[["render",r]]);export{c as __pageData,u as default};
